import math

def solve():
    satisfying_n = []
    for n in range(2, 21):
        is_valid = True
        # We only need to check k in the range 1 <= k < n, as this covers all units modulo n.
        for k in range(1, n):
            if math.gcd(k, n) == 1:
                # Check the condition: k^2 = 1 (mod n)
                if (k * k) % n != 1:
                    is_valid = False
                    break

        if is_valid:
            satisfying_n.append(n)

    print(f"Values of n satisfying the condition up to 20: {satisfying_n}")

