import math

candidates = [2, 3, 4, 6, 8, 12]
results = {}

for n in candidates:
    is_verified = True
    print(f"--- Verifying n = {n} ---")

    # Iterate through all potential k values (1 <= k < n)
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check the condition k^2 = 1 (mod n)
            if (k * k) % n != 1:
                print(f"Failure found for n={n} and k={k}. {k}^2 = {k*k}, {k*k} mod {n} = {(k*k)%n}, which is not 1.")
                is_verified = False
                break

    if is_verified:
        print(f"Success: k^2 = 1 (mod {n}) holds for all k coprime to {n}.")

    results[n] = is_verified

print("\n--- Summary ---")
print(results)

def check_condition(n):
    if n < 2:
        return False

    coprime_k = [k for k in range(1, n) if gcd(k, n) == 1]

    for k in coprime_k:
        # Check k^2 == 1 (mod n)
        if (k * k - 1) % n != 0:
            return f"Fails for k={k}. {k}^2 - 1 = {k*k - 1}, which is not divisible by {n}."
    return "Satisfies the condition."

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Test n=12
result_12 = check_condition(12)
print(f"Test n=12: {result_12}")

# Test n=16
result_16 = check_condition(16)
print(f"Test n=16: {result_16}")
